  have h_filter_subset : S.filter (fun m : ℤ => |(m : ℝ) - x| < L) ⊆ Finset.Ioo (⌊x - L⌋) (⌈x + L⌉) := by
    intro m hm; simp_all +decide [ abs_lt ] ;
    exact ⟨ Int.floor_lt.2 ( by linarith ), Int.lt_ceil.2 ( by linarith ) ⟩;
